    def __iter__(self):
        if self._cache_complete:
            return iter(self._cache)
        elif self._cache is None:
            return self._iter()
        else:
            return self._iter_cached()

    def _invalidate_cache(self):
        if self._cache is not None:
            self._cache = []
            self._cache_complete = False
            self._cache_gen = self._iter()

            if self._cache_lock.locked():
                self._cache_lock.release()

        self._len = None

    def _iter_cached(self):
        i = 0
        gen = self._cache_gen
        cache = self._cache
        acquire = self._cache_lock.acquire
        release = self._cache_lock.release
        while gen:
            if i == len(cache):
                acquire()
                if self._cache_complete:
                    break
                try:
                    for j in range(10):
                        cache.append(advance_iterator(gen))
                except StopIteration:
                    self._cache_gen = gen = None
                    self._cache_complete = True
                    break
                release()
            yield cache[i]
            i += 1
        while i < self._len:
            yield cache[i]
            i += 1

    def __getitem__(self, item):
        if self._cache_complete:
            return self._cache[item]
        elif isinstance(item, slice):
            if item.step and item.step < 0:
                return list(iter(self))[item]
            else:
                return list(itertools.islice(self,
                                             item.start or 0,
                                             item.stop or sys.maxsize,
                                             item.step or 1))
        elif item >= 0:
            gen = iter(self)
            try:
                for i in range(item+1):
                    res = advance_iterator(gen)
            except StopIteration:
                raise IndexError
            return res
        else:
            return list(iter(self))[item]

    def __contains__(self, item):
        if self._cache_complete:
            return item in self._cache
        else:
            for i in self:
                if i == item:
                    return True
                elif i > item:
                    return False
        return False

    # __len__() introduces a large performance penality.
    def count(self):
        """ Returns the number of recurrences in this set. It will have go
            trough the whole recurrence, if this hasn't been done before. """
        if self._len is None:
            for x in self:
                pass
        return self._len

    def before(self, dt, inc=False):
        """ Returns the last recurrence before the given datetime instance. The
            inc keyword defines what happens if dt is an occurrence. With
            inc=True, if dt itself is an occurrence, it will be returned. """
        if self._cache_complete:
            gen = self._cache
        else:
            gen = self
        last = None
        if inc:
            for i in gen:
                if i > dt:
                    break
                last = i
        else:
            for i in gen:
                if i >= dt:
                    break
                last = i
        return last

    def after(self, dt, inc=False):
        """ Returns the first recurrence after the given datetime instance. The
            inc keyword defines what happens if dt is an occurrence. With
            inc=True, if dt itself is an occurrence, it will be returned.  """
        if self._cache_complete:
            gen = self._cache
        else:
            gen = self
        if inc:
            for i in gen:
                if i >= dt:
                    return i
        else:
            for i in gen:
                if i > dt:
                    return i
        return None

    def xafter(self, dt, count=None, inc=False):
        """
        Generator which yields up to `count` recurrences after the given
        datetime instance, equivalent to `after`.

        :param dt:
            The datetime at which to start generating recurrences.

        :param count:
            The maximum number of recurrences to generate. If `None` (default),
            dates are generated until the recurrence rule is exhausted.

        :param inc:
            If `dt` is an instance of the rule and `inc` is `True`, it is
            included in the output.

        :yields: Yields a sequence of `datetime` objects.
        """

        if self._cache_complete:
            gen = self._cache
        else:
            gen = self

        # Select the comparison function
        if inc:
            comp = lambda dc, dtc: dc >= dtc
        else:
            comp = lambda dc, dtc: dc > dtc

        # Generate dates
        n = 0
        for d in gen:
            if comp(d, dt):
                yield d

                if count is not None:
                    n += 1
                    if n >= count:
                        break

    def between(self, after, before, inc=False, count=1):
        """ Returns all the occurrences of the rrule between after and before.
        The inc keyword defines what happens if after and/or before are
        themselves occurrences. With inc=True, they will be included in the
        list, if they are found in the recurrence set. """
        if self._cache_complete:
            gen = self._cache
        else:
            gen = self
        started = False
        l = []
        if inc:
            for i in gen:
                if i > before:
                    break
                elif not started:
                    if i >= after:
                        started = True
                        l.append(i)
                else:
                    l.append(i)
        else:
            for i in gen:
                if i >= before:
                    break
                elif not started:
                    if i > after:
                        started = True
                        l.append(i)
                else:
                    l.append(i)
        return l


class rrule(rrulebase):
    """
    That's the base of the rrule operation. It accepts all the keywords
    defined in the RFC as its constructor parameters (except byday,
    which was renamed to byweekday) and more. The constructor prototype is::

            rrule(freq)

    Where freq must be one of YEARLY, MONTHLY, WEEKLY, DAILY, HOURLY, MINUTELY,
    or SECONDLY.

    .. note::
        Per RFC section 3.3.10, recurrence instances falling on invalid dates
        and times are ignored rather than coerced:

            Recurrence rules may generate recurrence instances with an invalid
            date (e.g., February 30) or nonexistent local time (e.g., 1:30 AM
            on a day where the local time is moved forward by an hour at 1:00
            AM).  Such recurrence instances MUST be ignored and MUST NOT be
            counted as part of the recurrence set.

        This can lead to possibly surprising behavior when, for example, the
        start date occurs at the end of the month:

        >>> from dateutil.rrule import rrule, MONTHLY
        >>> from datetime import datetime
        >>> start_date = datetime(2014, 12, 31)
        >>> list(rrule(freq=MONTHLY, count=4, dtstart=start_date))
        ... # doctest: +NORMALIZE_WHITESPACE
        [datetime.datetime(2014, 12, 31, 0, 0),
         datetime.datetime(2015, 1, 31, 0, 0),
         datetime.datetime(2015, 3, 31, 0, 0),
         datetime.datetime(2015, 5, 31, 0, 0)]

    Additionally, it supports the following keyword arguments:

    :param cache:
        If given, it must be a boolean value specifying to enable or disable
        caching of results. If you will use the same rrule instance multiple
        times, enabling caching will improve the performance considerably.
    :param dtstart:
        The recurrence start. Besides being the base for the recurrence,
        missing parameters in the final recurrence instances will also be
        extracted from this date. If not given, datetime.now() will be used
        instead.
    :param interval:
        The interval between each freq iteration. For example, when using
        YEARLY, an interval of 2 means once every two years, but with HOURLY,
        it means once every two hours. The default interval is 1.
    :param wkst:
        The week start day. Must be one of the MO, TU, WE constants, or an
        integer, specifying the first day of the week. This will affect
        recurrences based on weekly periods. The default week start is got
        from calendar.firstweekday(), and may be modified by
        calendar.setfirstweekday().
    :param count:
        How many occurrences will be generated.

        .. note::
            As of version 2.5.0, the use of the ``until`` keyword together
            with the ``count`` keyword is deprecated per RFC-2445 Sec. 4.3.10.
    :param until:
        If given, this must be a datetime instance, that will specify the
        limit of the recurrence. The last recurrence in the rule is the greatest
        datetime that is less than or equal to the value specified in the
        ``until`` parameter.

        .. note::
            As of version 2.5.0, the use of the ``until`` keyword together
            with the ``count`` keyword is deprecated per RFC-2445 Sec. 4.3.10.
    :param bysetpos:
        If given, it must be either an integer, or a sequence of integers,
        positive or negative. Each given integer will specify an occurrence
        number, corresponding to the nth occurrence of the rule inside the
        frequency period. For example, a bysetpos of -1 if combined with a
        MONTHLY frequency, and a byweekday of (MO, TU, WE, TH, FR), will
        result in the last work day of every month.
    :param bymonth:
        If given, it must be either an integer, or a sequence of integers,
        meaning the months to apply the recurrence to.
    :param bymonthday:
        If given, it must be either an integer, or a sequence of integers,
        meaning the month days to apply the recurrence to.
    :param byyearday:
        If given, it must be either an integer, or a sequence of integers,
        meaning the year days to apply the recurrence to.
    :param byweekno:
        If given, it must be either an integer, or a sequence of integers,
        meaning the week numbers to apply the recurrence to. Week numbers
        have the meaning described in ISO8601, that is, the first week of
        the year is that containing at least four days of the new year.
    :param byweekday:
        If given, it must be either an integer (0 == MO), a sequence of
        integers, one of the weekday constants (MO, TU, etc), or a sequence
        of these constants. When given, these variables will define the
        weekdays where the recurrence will be applied. It's also possible to
        use an argument n for the weekday instances, which will mean the nth
        occurrence of this weekday in the period. For example, with MONTHLY,
        or with YEARLY and BYMONTH, using FR(+1) in byweekday will specify the
        first friday of the month where the recurrence happens. Notice that in
        the RFC documentation, this is specified as BYDAY, but was renamed to

    the RFC documentation, this is specified as BYDAY, but was renamed to
    avoid the ambiguity of that keyword.
:param byhour:
    If given, it must be either an integer, or a sequence of integers,
    meaning the hours to apply the recurrence to.
:param byminute:
    If given, it must be either an integer, or a sequence of integers,
    meaning the minutes to apply the recurrence to.
:param bysecond:
    If given, it must be either an integer, or a sequence of integers,
    meaning the seconds to apply the recurrence to.
:param byeaster:
    If given, it must be either an integer, or a sequence of integers,
    positive or negative. Each integer will define an offset from the
    Easter Sunday. Passing the offset 0 to byeaster will yield the Easter
    Sunday itself. This is an extension to the RFC specification.
 """
def __init__(self, freq, dtstart=None,
             interval=1, wkst=None, count=None, until=None, bysetpos=None,
             bymonth=None, bymonthday=None, byyearday=None, byeaster=None,
             byweekno=None, byweekday=None,
             byhour=None, byminute=None, bysecond=None,
             cache=False):
    super(rrule, self).__init__(cache)
    global easter
    if not dtstart:
        dtstart = datetime.datetime.now().replace(microsecond=0)
    elif not isinstance(dtstart, datetime.datetime):
        dtstart = datetime.datetime.fromordinal(dtstart.toordinal())
    else:
        dtstart = dtstart.replace(microsecond=0)
    self._dtstart = dtstart
    self._tzinfo = dtstart.tzinfo
    self._freq = freq
    self._interval = interval
    self._count = count

    # Cache the original byxxx rules, if they are provided, as the _byxxx
    # attributes do not necessarily map to the inputs, and this can be
    # a problem in generating the strings. Only store things if they've
    # been supplied (the string retrieval will just use .get())
    self._original_rule = {}

    if until and not isinstance(until, datetime.datetime):
        until = datetime.datetime.fromordinal(until.toordinal())
    self._until = until

    if count and until:
        warn("Using both 'count' and 'until' is inconsistent with RFC 2445"
             " and has been deprecated in dateutil. Future versions will "
             "raise an error.", DeprecationWarning)

    if wkst is None:
        self._wkst = calendar.firstweekday()
    elif isinstance(wkst, integer_types):
        self._wkst = wkst
    else:
        self._wkst = wkst.weekday

    if bysetpos is None:
        self._bysetpos = None
    elif isinstance(bysetpos, integer_types):
        if bysetpos == 0 or not (-366 <= bysetpos <= 366):
            raise ValueError("bysetpos must be between 1 and 366, "
                             "or between -366 and -1")
        self._bysetpos = (bysetpos,)
    else:
        self._bysetpos = tuple(bysetpos)
        for pos in self._bysetpos:
            if pos == 0 or not (-366 <= pos <= 366):
                raise ValueError("bysetpos must be between 1 and 366, "
                                 "or between -366 and -1")

    if self._bysetpos:
        self._original_rule['bysetpos'] = self._bysetpos

    if (byweekno is None and byyearday is None and bymonthday is None and
            byweekday is None and byeaster is None):
        if freq == YEARLY:
            if bymonth is None:
                bymonth = dtstart.month
                self._original_rule['bymonth'] = None
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == MONTHLY:
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == WEEKLY:
            byweekday = dtstart.weekday()
            self._original_rule['byweekday'] = None

    # bymonth
    if bymonth is None:
        self._bymonth = None
    else:
        if isinstance(bymonth, integer_types):
            bymonth = (bymonth,)

        self._bymonth = tuple(sorted(set(bymonth)))

        if 'bymonth' not in self._original_rule:
            self._original_rule['bymonth'] = self._bymonth

    # byyearday
    if byyearday is None:
        self._byyearday = None
    else:
        if isinstance(byyearday, integer_types):
            byyearday = (byyearday,)

        self._byyearday = tuple(sorted(set(byyearday)))
        self._original_rule['byyearday'] = self._byyearday

    # byeaster
    if byeaster is not None:
        if not easter:
            from dateutil import easter
        if isinstance(byeaster, integer_types):
            self._byeaster = (byeaster,)
        else:
            self._byeaster = tuple(sorted(byeaster))

        self._original_rule['byeaster'] = self._byeaster
    else:
        self._byeaster = None

    # bymonthday
    if bymonthday is None:
        self._bymonthday = ()
        self._bynmonthday = ()
    else:
        if isinstance(bymonthday, integer_types):
            bymonthday = (bymonthday,)

        bymonthday = set(bymonthday)            # Ensure it's unique

        self._bymonthday = tuple(sorted([x for x in bymonthday if x > 0]))
        self._bynmonthday = tuple(sorted([x for x in bymonthday if x < 0]))

        # Storing positive numbers first, then negative numbers
        if 'bymonthday' not in self._original_rule:
            self._original_rule['bymonthday'] = tuple(
                itertools.chain(self._bymonthday, self._bynmonthday))

    # byweekno
    if byweekno is None:
        self._byweekno = None
    else:
        if isinstance(byweekno, integer_types):
            byweekno = (byweekno,)

        self._byweekno = tuple(sorted(set(byweekno)))

        self._original_rule['byweekno'] = self._byweekno

    # byweekday / bynweekday
    if byweekday is None:
        self._byweekday = None
        self._bynweekday = None
    else:
        # If it's one of the valid non-sequence types, convert to a
        # single-element sequence before the iterator that builds the
        # byweekday set.
        if isinstance(byweekday, integer_types) or hasattr(byweekday, "n"):
            byweekday = (byweekday,)

        self._byweekday = set()
        self._bynweekday = set()
        for wday in byweekday:
            if isinstance(wday, integer_types):
                self._byweekday.add(wday)
            elif not wday.n or freq > MONTHLY:
                self._byweekday.add(wday.weekday)
            else:
                self._bynweekday.add((wday.weekday, wday.n))

        if not self._byweekday:
            self._byweekday = None
        elif not self._bynweekday:
            self._bynweekday = None

        if self._byweekday is not None:
            self._byweekday = tuple(sorted(self._byweekday))
            orig_byweekday = [weekday(x) for x in self._byweekday]
        else:
            orig_byweekday = tuple()

        if self._bynweekday is not None:
            self._bynweekday = tuple(sorted(self._bynweekday))
            orig_bynweekday = [weekday(*x) for x in self._bynweekday]
        else:
            orig_bynweekday = tuple()

        if 'byweekday' not in self._original_rule:
            self._original_rule['byweekday'] = tuple(itertools.chain(
                orig_byweekday, orig_bynweekday))

    # byhour
    if byhour is None:
        if freq < HOURLY:
            self._byhour = set((dtstart.hour,))
        else:
            self._byhour = None
    else:
        if isinstance(byhour, integer_types):
            byhour = (byhour,)

        if freq == HOURLY:
            self._byhour = self.__construct_byset(start=dtstart.hour,
                                                  byxxx=byhour,
                                                  base=24)
        else:
            self._byhour = set(byhour)

        self._byhour = tuple(sorted(self._byhour))
        self._original_rule['byhour'] = self._byhour

    # byminute
    if byminute is None:
        if freq < MINUTELY:
            self._byminute = set((dtstart.minute,))
        else:
            self._byminute = None
    else:
        if isinstance(byminute, integer_types):
            byminute = (byminute,)

        if freq == MINUTELY:
            self._byminute = self.__construct_byset(start=dtstart.minute,
                                                    byxxx=byminute,
                                                    base=60)
        else:
            self._byminute = set(byminute)

        self._byminute = tuple(sorted(self._byminute))
        self._original_rule['byminute'] = self._byminute

    # bysecond
    if bysecond is None:
        if freq < SECONDLY:
            self._bysecond = ((dtstart.second,))
        else:
            self._bysecond = None
    else:
        if isinstance(bysecond, integer_types):
            bysecond = (bysecond,)

        self._bysecond = set(bysecond)

        if freq == SECONDLY:
            self._bysecond = self.__construct_byset(start=dtstart.second,
                                                    byxxx=bysecond,
                                                    base=60)
        else:
            self._bysecond = set(bysecond)

        self._bysecond = tuple(sorted(self._bysecond))
        self._original_rule['bysecond'] = self._bysecond

    if self._freq >= HOURLY:
        self._timeset = None
    else:
        self._timeset = []
        for hour in self._byhour:
            for minute in self._byminute:
                for second in self._bysecond:
                    self._timeset.append(
                        datetime.time(hour, minute, second,
                                      tzinfo=self._tzinfo))
        self._timeset.sort()
        self._timeset = tuple(self._timeset)

def __str__(self):
    """
    Output a string that would generate this RRULE if passed to rrulestr.
    This is mostly compatible with RFC2445, except for the
    dateutil-specific extension BYEASTER.
    """

    output = []
    h, m, s = [None] * 3
    if self._dtstart:
        output.append(self._dtstart.strftime('DTSTART:%Y%m%dT%H%M%S'))
        h, m, s = self._dtstart.timetuple()[3:6]

